1	/**
2	 * Daemon-side OpenCode server manager. Spawns one `opencode serve` child per
3	 * task and exposes a stable base URL for the SDK-based `OpenCodeAdapter` to
4	 * connect to.
5	 *
6	 * Ported from commercial `1a320029:apps/desktop/src/main/opencode/server-manager.ts`
7	 * with Electron dependencies stripped (no `@sentry/electron/main`, no
8	 * `./electron-options`). Daemon-flavour adaptations:
9	 *
10	 *   - Logging routed through pino via `./logger` instead of Sentry.
11	 *   - `opencode` binary resolved from the `opencode-ai` npm package via
12	 *     `require.resolve`, matching how the Phase 0 SDK spike validated it.
13	 *   - Environment + pre-flight (API-key sync, config-generation) delegated
14	 *     to the existing `task-config-builder` helpers so we don't duplicate
15	 *     desktop's pre-cutover logic.
16	 *
17	 * Lifecycle decisions (per plan decision #9):
18	 *   - Crash detection on child `exit`: notifyClosed fires so owners can
19	 *     emit a clean task-failure event.
20	 *   - Clean termination: SIGTERM then SIGKILL; POSIX process-group kill
21	 *     reaps grandchildren; Windows taskkill /T /F.
22	 *   - Daemon-shutdown cleanup: `process.on('exit', ...)` iterates every
23	 *     tracked PID and kills it. Hooked once on first runtime start.
24	 *   - Port-leak prevention: the tracked-PID registry combined with
25	 *     exit-hook cleanup prevents daemon restarts from orphaning servers.
26	 *     Startup zombie sweep (for crashed-daemon recovery) is not included
27	 *     here; that is a separate pid-file/state-directory concern to add
28	 *     later if it becomes a real problem.
29	 *
30	 * Part of the OpenCode SDK cutover port (Phase 2 of commercial PR #720).
31	 */
32	
33	import { spawn, spawnSync, type ChildProcess } from 'child_process';
34	import {
35	  resolveCliPath,
36	  type StorageAPI,
37	  type AccomplishRuntime,
38	  type CliResolverConfig,
39	  type OnBeforeStartContext,
40	} from '@accomplish_ai/agent-core';
41	import { createOpencodeClient, type OpencodeClient } from '@opencode-ai/sdk/v2';
42	
43	import { log } from '../logger.js';
44	import { onBeforeStart, type TaskConfigBuilderOptions } from '../task-config-builder.js';
45	
46	const READY_TIMEOUT_MS = 15_000;
47	const SERVER_URL_WAIT_TIMEOUT_MS = 10_000;
48	/**
49	 * Keep a short reuse window after a task completes so an immediate follow-up
50	 * task (e.g. resume) stays fast without leaving a finished runtime alive
51	 * forever.
52	 */
53	const TASK_RUNTIME_IDLE_CLEANUP_MS = 60_000;
54	
55	interface TrackedOpencodeServerHandle {
56	  url: string;
57	  close(): void;
58	}
59	
60	/**
61	 * Dependencies the server-manager needs to resolve per-task runtime config.
62	 * Passed once at construction instead of reading from globals so the daemon
63	 * can inject its storage, paths, and optional runtime hooks.
64	 */
65	export interface ServerManagerDeps extends TaskConfigBuilderOptions {
66	  storage: StorageAPI;
67	  /** Optional Accomplish runtime context (proxy, credits, etc.); daemon wires it. */
68	  accomplishRuntime?: AccomplishRuntime;
69	}
70	
71	// ──────────────────────────── process-tree management ──────────────────────
72	
73	const activeRuntimePids = new Set<number>();
74	let runtimeCleanupRegistered = false;
75	
76	function ensureRuntimeCleanupRegistered(): void {
77	  if (runtimeCleanupRegistered) return;
78	  runtimeCleanupRegistered = true;
79	  process.on('exit', () => {
80	    for (const pid of activeRuntimePids) {
81	      killProcessTree(pid);
82	    }
83	  });
84	}
85	
86	function killProcessTree(pid: number): void {
87	  if (!Number.isInteger(pid) || pid <= 0) return;
88	
89	  if (process.platform === 'win32') {
90	    spawnSync('taskkill', ['/PID', String(pid), '/T', '/F'], {
91	      stdio: ['ignore', 'ignore', 'ignore'],
92	      timeout: 2000,
93	      windowsHide: true,
94	    });
95	    return;
96	  }
97	
98	  // POSIX: kill the whole process group so grandchildren (e.g. plugins) go too.
99	  try {
100	    process.kill(-pid, 'SIGKILL');
101	    return;
102	  } catch {
103	    spawnSync('pkill', ['-9', '-P', String(pid)], {
104	      stdio: ['ignore', 'ignore', 'ignore'],
105	      timeout: 2000,
106	    });
107	  }
108	
109	  try {
110	    process.kill(pid, 'SIGKILL');
111	  } catch {
112	    // Process already exited — fine.
113	  }
114	}
115	
116	function trackRuntimePid(proc: ChildProcess): number {
117	  if (!proc.pid) {
118	    throw new Error('OpenCode server process did not expose a pid');
119	  }
120	  const pid = proc.pid;
121	  ensureRuntimeCleanupRegistered();
122	  activeRuntimePids.add(pid);
123	  proc.once('exit', () => {
124	    activeRuntimePids.delete(pid);
125	  });
126	  return pid;
127	}
128	
129	// ──────────────────────────── binary resolution ────────────────────────────
130	
131	let cachedOpencodeBinPath: string | null = null;
132	
133	/**
134	 * Resolve the `opencode` CLI binary using the SAME resolver agent-core's
135	 * `isCliAvailable` uses. Earlier drafts of this function called
136	 * `require.resolve('opencode-ai/package.json')` directly, but in the
137	 * tsup-bundled CJS daemon the search root is `apps/daemon/dist/`, which has
138	 * no `node_modules/opencode-ai/`. The bundled-app form is
139	 * `${resourcesPath}/app.asar.unpacked/node_modules/opencode-ai/bin/opencode`;
140	 * the dev form is `${appPath}/node_modules/.bin/opencode`. Both are handled
141	 * by `resolveCliPath` so the daemon doesn't need to re-implement the
142	 * lookup. Cached after the first successful resolution.
143	 *
144	 * Throws when the CLI cannot be located — the per-task runtime can't spawn
145	 * `opencode serve` without it. The error message matches what the daemon
146	 * reports through the RPC layer for consistency.
147	 */
148	function getOpencodeBinPath(deps: TaskConfigBuilderOptions): string {
149	  if (cachedOpencodeBinPath) return cachedOpencodeBinPath;
150	
151	  const cliConfig: CliResolverConfig = {
152	    isPackaged: deps.isPackaged,
153	    resourcesPath: deps.resourcesPath,
154	    appPath: deps.appPath,
155	  };
156	  const resolved = resolveCliPath(cliConfig);
157	  if (!resolved) {
158	    throw new Error(
159	      `Cannot locate opencode-ai CLI. resolveCliPath returned null for ` +
160	        `(isPackaged=${deps.isPackaged}, resourcesPath=${deps.resourcesPath}, appPath=${deps.appPath}).`,
161	    );
162	  }
163	  cachedOpencodeBinPath = resolved.cliPath;
164	  return resolved.cliPath;
165	}
166	
167	// ──────────────────────────── low-level spawn ──────────────────────────────
168	
169	function parseServerUrlFromOutput(line: string): string | null {
170	  if (!line.startsWith('opencode server listening')) return null;
171	  const match = line.match(/on\s+(https?:\/\/[^\s]+)/);
172	  return match?.[1] ?? null;
173	}
174	
175	function spawnOpenCodeServer(
176	  runtimeEnv: NodeJS.ProcessEnv,
177	  deps: TaskConfigBuilderOptions,
178	  signal?: AbortSignal,
179	  onClosed?: () => void,
180	): Promise<TrackedOpencodeServerHandle> {
181	  const command = getOpencodeBinPath(deps);
182	  const args = ['serve', '--hostname=127.0.0.1', '--port=0'];
183	  // Merge runtimeEnv (per-task config: OPENCODE_CONFIG, OPENCODE_CONFIG_DIR,
184	  // and PATH if onBeforeStart prepended bundled Node) ON TOP of process.env
185	  // so the spawned `opencode` shim inherits PATH, HOME, XDG_*, locale, etc.
186	  // Without this merge the shim runs in a near-empty env and the wrapper
187	  // shell script can't `exec node`. The runtime overrides win on conflict.
188	  const mergedEnv: NodeJS.ProcessEnv = { ...process.env, ...runtimeEnv };
189	  const proc = spawn(command, args, {
190	    detached: process.platform !== 'win32',
191	    env: mergedEnv,
192	    signal,
193	    stdio: ['ignore', 'pipe', 'pipe'],
194	    windowsHide: true,
195	  });
196	
197	  return new Promise((resolve, reject) => {
198	    let runtimePid: number | null = null;
199	    let output = '';
200	    let stdoutBuffer = '';
201	    let settled = false;
202	    let closed = false;
203	    let closeNotified = false;
204	
205	    const readyTimeout = setTimeout(() => {
206	      settle(() => {
207	        close();
208	        reject(new Error(`Timeout waiting for server to start after ${READY_TIMEOUT_MS}ms`));
209	      });
210	    }, READY_TIMEOUT_MS);
211	
212	    const settle = (callback: () => void): void => {
213	      if (settled) return;
214	      settled = true;
215	      clearTimeout(readyTimeout);
216	      proc.stdout?.removeListener('data', onStdout);
217	      proc.stderr?.removeListener('data', onStderr);
218	      signal?.removeEventListener('abort', onAbort);
219	      callback();
220	    };
221	
222	    const notifyClosed = (): void => {
223	      if (closeNotified) return;
224	      closeNotified = true;
225	      onClosed?.();
226	    };
227	
228	    const close = (): void => {
229	      if (closed) return;
230	      closed = true;
231	      if (runtimePid !== null) {
232	        activeRuntimePids.delete(runtimePid);
233	        killProcessTree(runtimePid);
234	      }
235	    };
236	
237	    const onStdout = (chunk: Buffer | string): void => {
238	      const text = chunk.toString();
239	      output += text;
240	      stdoutBuffer += text;
241	      const lines = stdoutBuffer.split('\n');
242	      stdoutBuffer = lines.pop() ?? '';
243	
244	      for (const rawLine of lines) {
245	        const trimmed = rawLine.trim();
246	        if (!trimmed) continue;
247	        // Forward opencode's own stdout into the daemon log. Previously we
248	        // captured stdout silently for ready-line parsing, which made it
249	        // impossible to see what opencode was doing during long-running
250	        // flows like OAuth. Forwarding gives direct visibility — the cost
251	        // is a little more log noise on successful task runs.
252	        if (settled) {
253	          log.info(`[opencode:stdout] ${trimmed}`);
254	        }
255	        const url = parseServerUrlFromOutput(trimmed);
256	        if (!url) continue;
257	        settle(() => {
258	          log.info(`[opencode:stdout] ${trimmed}`);
259	          resolve({ url, close });
260	        });
261	        return;
262	      }
263	    };
264	
265	    const onStderr = (chunk: Buffer | string): void => {
266	      const text = chunk.toString();
267	      output += text;
268	      // Forward opencode's own stderr too — schema validation failures,
269	      // port conflicts, OAuth exchange errors all land here.
270	      for (const rawLine of text.split('\n')) {
271	        const trimmed = rawLine.trim();
272	        if (trimmed) log.warn(`[opencode:stderr] ${trimmed}`);
273	      }
274	    };
275	
276	    const onExit = (code: number | null): void => {
277	      close();
278	      notifyClosed();
279	      // Always log the exit so silent child-process deaths are visible.
280	      log.warn(
281	        `[opencode:exit] opencode-serve exited with code ${code} after ${output.trim().length} bytes of output (settled=${settled})`,
282	      );
283	      if (settled) return;
284	      settle(() => {
285	        let message = `OpenCode server exited with code ${code}`;
286	        if (output.trim()) message += `\nServer output: ${output}`;
287	        reject(new Error(message));
288	      });
289	    };
290	
291	    const onError = (error: Error): void => {
292	      close();
293	      notifyClosed();
294	      if (settled) return;
295	      settle(() => {
296	        reject(error);
297	      });
298	    };
299	
300	    const onAbort = (): void => {
301	      settle(() => {
302	        close();
303	        const error = new Error('Aborted');
304	        error.name = 'AbortError';
305	        reject(error);
306	      });
307	    };
308	
309	    proc.stdout?.on('data', onStdout);
310	    proc.stderr?.on('data', onStderr);
311	    proc.on('exit', onExit);
312	    proc.on('error', onError);
313	    signal?.addEventListener('abort', onAbort, { once: true });
314	
315	    if (proc.pid) {
316	      runtimePid = trackRuntimePid(proc);
317	    }
318	  });
319	}
320	
321	function throwIfStartAborted(signal?: AbortSignal): void {
322	  if (!signal?.aborted) return;
323	  const error = new Error('Task runtime start aborted');
324	  error.name = 'AbortError';
325	  throw error;
326	}
327	
328	// ──────────────────────────── per-task runtime ─────────────────────────────
329	
330	class OpenCodeTaskRuntime {
331	  private server: TrackedOpencodeServerHandle | null = null;
332	  private serverUrl: string | undefined;
333	  private ready = false;
334	  private startPromise: Promise<void> | null = null;
335	  private startAbortController: AbortController | null = null;
336	  private disposed = false;
337	  /**
338	   * Per-task context forwarded to `onBeforeStart`. Populated by
339	   * `ensureTaskRuntime(taskId, ctx)`. Defaults to `{ taskId }` so runtimes
340	   * spawned by code paths that predate the workspace-aware task path
341	   * (transient OAuth client, future callers) still get a taskId at
342	   * minimum — `prepareGwsManifest` etc. only need the `workspaceId` when
343	   * it's actually present.
344	   */
345	  private ctx: OnBeforeStartContext;
346	
347	  constructor(
348	    readonly taskId: string,
349	    private readonly deps: ServerManagerDeps,
350	  ) {
351	    this.ctx = { taskId };
352	  }
353	
354	  /**
355	   * Update the per-task context. Called by the manager before `start()` /
356	   * on follow-up `ensureTaskRuntime` calls so the latest workspace context
357	   * reaches `onBeforeStart` if the runtime is still warm from a previous
358	   * task step.
359	   */
360	  setContext(ctx: OnBeforeStartContext): void {
361	    this.ctx = { taskId: this.taskId, ...ctx };
362	  }
363	
364	  isReady(): boolean {
365	    return this.ready;
366	  }
367	
368	  async waitForServerUrl(): Promise<string | undefined> {
369	    if (this.ready && this.serverUrl) return this.serverUrl;
370	    const deadline = Date.now() + SERVER_URL_WAIT_TIMEOUT_MS;
371	
372	    while (true) {
373	      if (this.disposed) return undefined;
374	      if (this.ready && this.serverUrl) return this.serverUrl;
375	      if (Date.now() > deadline) return undefined;
376	      await new Promise((r) => setTimeout(r, 50));
377	    }
378	  }
379	
380	  async start(): Promise<void> {
381	    if (this.disposed) return;
382	    if (this.ready) return;
383	    if (this.startPromise) return this.startPromise;
384	
385	    this.startAbortController = new AbortController();
386	    const signal = this.startAbortController.signal;
387	
388	    this.startPromise = this.doStart(signal).finally(() => {
389	      this.startPromise = null;
390	    });
391	    return this.startPromise;
392	  }
393	
394	  private async doStart(signal: AbortSignal): Promise<void> {
395	    const startedAt = performance.now();
396	    try {
397	      throwIfStartAborted(signal);
398	      const { env: runtimeEnv } = await onBeforeStart(this.deps.storage, this.deps, this.ctx);
399	      throwIfStartAborted(signal);
400	
401	      const spawnedServer = await spawnOpenCodeServer(runtimeEnv, this.deps, signal, () => {
402	        // Runtime-side `onClosed`: the child exited independently. Flip state
403	        // so `isReady()` reflects reality; the adapter consumes its own
404	        // `session.error` SDK event stream to report task-level failures.
405	        if (this.disposed) return;
406	        this.ready = false;
407	        this.serverUrl = undefined;
408	        this.server = null;
409	      });
410	      this.server = spawnedServer;
411	
412	      if (signal.aborted) {
413	        await this.stop();
414	        return;
415	      }
416	
417	      this.serverUrl = this.server.url;
418	      this.ready = true;
419	      log.info(
420	        `[OpenCode Server] Task runtime ${this.taskId} ready in ${(
421	          performance.now() - startedAt
422	        ).toFixed(0)}ms at ${this.serverUrl}`,
423	      );
424	    } catch (error) {
425	      if (error instanceof Error && error.name === 'AbortError') {
426	        await this.stop();
427	        return;
428	      }
429	      log.warn(
430	        `[OpenCode Server] Failed to start task runtime ${this.taskId}: ${
431	          error instanceof Error ? error.message : String(error)
432	        }`,
433	      );
434	      await this.stop();
435	      throw error;
436	    }
437	  }
438	
439	  async stop(): Promise<void> {
440	    this.ready = false;
441	    this.serverUrl = undefined;
442	    const serverToStop = this.server;
443	    this.server = null;
444	    if (!serverToStop) return;
445	    serverToStop.close();
446	  }
447	
448	  abortStart(): void {
449	    this.startAbortController?.abort();
450	  }
451	
452	  async waitForStartToSettle(): Promise<void> {
453	    if (this.startPromise) await this.startPromise;
454	  }
455	
456	  dispose(): void {
457	    this.disposed = true;
458	    this.abortStart();
459	    void this.stop();
460	  }
461	}
462	
463	// ──────────────────────────── manager (singleton per daemon) ───────────────
464	
465	export class OpenCodeServerManager {
466	  private runtimes = new Map<string, OpenCodeTaskRuntime>();
467	  private cleanupTimers = new Map<string, ReturnType<typeof setTimeout>>();
468	  private disposed = false;
469	
470	  constructor(private readonly deps: ServerManagerDeps) {}
471	
472	  isReady(taskId: string): boolean {
473	    return this.runtimes.get(taskId)?.isReady() ?? false;
474	  }
475	
476	  async ensureTaskRuntime(taskId: string, ctx?: OnBeforeStartContext): Promise<void> {
477	    if (!taskId || this.disposed) return;
478	    this.clearCleanupTimer(taskId);
479	    const runtime = this.getOrCreateRuntime(taskId);
480	    if (ctx) {
481	      runtime.setContext(ctx);
482	    }
483	    await runtime.start();
484	  }
485	
486	  async waitForServerUrl(taskId: string): Promise<string | undefined> {
487	    if (!taskId || this.disposed) return undefined;
488	    this.clearCleanupTimer(taskId);
489	    return this.runtimes.get(taskId)?.waitForServerUrl();
490	  }
491	
492	  scheduleTaskRuntimeCleanup(taskId: string, delayMs = TASK_RUNTIME_IDLE_CLEANUP_MS): void {
493	    if (!taskId || this.disposed || !this.runtimes.has(taskId)) return;
494	    this.clearCleanupTimer(taskId);
495	    const timer = setTimeout(() => {
496	      this.cleanupTimers.delete(taskId);
497	      void this.destroyTaskRuntime(taskId).catch((error) => {
498	        log.warn(
499	          `[OpenCode Server] Failed to clean up task runtime ${taskId}: ${
500	            error instanceof Error ? error.message : String(error)
501	          }`,
502	        );
503	      });
504	    }, delayMs);
505	    this.cleanupTimers.set(taskId, timer);
506	  }
507	
508	  async destroyTaskRuntime(taskId: string): Promise<void> {
509	    const runtime = this.runtimes.get(taskId);
510	    if (!runtime) return;
511	    this.clearCleanupTimer(taskId);
512	    this.runtimes.delete(taskId);
513	    runtime.abortStart();
514	    await runtime.stop();
515	    await runtime.waitForStartToSettle();
516	  }
517	
518	  async destroyAllTaskRuntimes(): Promise<void> {
519	    const taskIds = [...this.runtimes.keys()];
520	    await Promise.all(taskIds.map((taskId) => this.destroyTaskRuntime(taskId)));
521	  }
522	
523	  async invalidate(): Promise<void> {
524	    if (this.disposed) return;
525	    log.info('[OpenCode Server] Invalidating all task runtimes...');
526	    await this.destroyAllTaskRuntimes();
527	  }
528	
529	  dispose(): void {
530	    this.disposed = true;
531	    for (const timer of this.cleanupTimers.values()) clearTimeout(timer);
532	    this.cleanupTimers.clear();
533	    for (const runtime of this.runtimes.values()) runtime.dispose();
534	    this.runtimes.clear();
535	  }
536	
537	  /**
538	   * Returns a closure suitable for `TaskAdapterOptions.getServerUrl`.
539	   * Used by the daemon when constructing the adapter: the adapter calls this
540	   * every task start to get its runtime URL.
541	   */
542	  getServerUrlResolver(): (taskId: string) => Promise<string | undefined> {
543	    return async (taskId: string) => this.waitForServerUrl(taskId);
544	  }
545	
546	  private getOrCreateRuntime(taskId: string): OpenCodeTaskRuntime {
547	    this.clearCleanupTimer(taskId);
548	    const existing = this.runtimes.get(taskId);
549	    if (existing) return existing;
550	    const runtime = new OpenCodeTaskRuntime(taskId, this.deps);
551	    this.runtimes.set(taskId, runtime);
552	    return runtime;
553	  }
554	
555	  private clearCleanupTimer(taskId: string): void {
556	    const timer = this.cleanupTimers.get(taskId);
557	    if (!timer) return;
558	    clearTimeout(timer);
559	    this.cleanupTimers.delete(taskId);
560	  }
561	}
562	
563	// ──────────────────────────── transient client (OAuth / Phase 4a) ──────────
564	
565	/**
566	 * Start a short-lived `opencode serve` instance and return an SDK client
567	 * bound to it. Used by the OAuth daemon RPC (Phase 4a) which needs to drive
568	 * the SDK auth flow once per login attempt and then tear down.
569	 *
570	 * NOT used by the task-execution path — tasks use `OpenCodeServerManager`
571	 * directly so runtimes can be pooled / cleaned up per-task.
572	 */
573	export async function createTransientOpencodeClient(
574	  deps: ServerManagerDeps,
575	  signal?: AbortSignal,
576	): Promise<{ client: OpencodeClient; close: () => void }> {
577	  throwIfStartAborted(signal);
578	  // No task context for the OAuth flow — pass an empty ctx. The daemon's
579	  // onBeforeStart uses this to skip workspace/config-filename specifics and
580	  // write the default `opencode.json` for OAuth.
581	  const { env: runtimeEnv } = await onBeforeStart(deps.storage, deps, {});
582	  throwIfStartAborted(signal);
583	  const server = await spawnOpenCodeServer(runtimeEnv, deps, signal);
584	  return {
585	    client: createOpencodeClient({ baseUrl: server.url }),
586	    close: () => server.close(),
587	  };
588	}
